contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= v);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(balAfter + (reverted ? 0 : v) == balBefore && countAfter == countBefore);
    }

    receive() external payable {}
}

